input.command:
cd /workspace/data
time duckdb -c "
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs;
SET http_keep_alive=true;
COPY (
  SELECT cod_tema,nom_tema,cod_imovel,mod_fiscal,num_area,ind_status,ind_tipo,des_condic,municipio,cod_estado,dat_criaca,dat_atuali,
         ST_AsWKB(geometry) AS geom_wkb
  FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet')
  WHERE cod_imovel IN (SELECT column0 FROM read_csv('/workspace/lists/goias-sample.csv', header=true, columns={'column0':'VARCHAR','column1':'VARCHAR','column2':'VARCHAR'}))
) TO 'car_listed.parquet' (FORMAT parquet);
SELECT count(*) AS rows_extracted FROM read_parquet('car_listed.parquet');
"

cd /workspace/data
time duckdb -c "
LOAD httpfs;
SELECT count(*) AS n_rows, count(DISTINCT cod_imovel) AS n_distinct
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet');
"

cd /workspace/data
duckdb -c "
LOAD spatial;
SELECT 'facilities_tiers' t; 
SELECT tier, count(*) n FROM read_parquet('BR_facilities.parquet') GROUP BY tier ORDER BY tier;
SELECT '--- trazo rows ---';
SELECT count(*) n_rows FROM read_parquet('trazo_goias.parquet');
SELECT '--- list distinct ---';
SELECT count(*) total, count(DISTINCT column0) distinct_ids FROM read_csv('/workspace/lists/goias-sample.csv', header=true, columns={'column0':'VARCHAR','column1':'VARCHAR','column2':'VARCHAR'});
"

cd /workspace/data
rm -f work.db
time duckdb work.db -c "
LOAD spatial;
CREATE TABLE parcels AS
  SELECT cod_imovel, num_area, municipio, ST_GeomFromWKB(geom_wkb) AS geom
  FROM read_parquet('car_listed.parquet');
-- overall envelope of all listed parcels
CREATE TABLE env AS SELECT ST_Extent(ST_Extent_Agg(geom)) AS e FROM parcels;
SELECT ST_AsText(ST_Extent_Agg(geom)) FROM parcels;
"

cd /workspace/data
time duckdb work.db -c "
LOAD spatial;
CREATE TABLE envpoly AS SELECT ST_Extent_Agg(geom) AS e FROM parcels;
CREATE TABLE fields_env AS
  SELECT t.Id, t.hansen_covered_area, t.hansen_loss_area, t.mode_year, t.firstyear, t.firstyearmajority,
         t.deforestarea0104, t.deforestarea0509, t.deforestarea1014, t.deforestarea1520, t.deforestarea2124,
         t.mbmode24, t.mbcov_area_2024, t.mbvalid_area_2024, t.geometry AS geom
  FROM read_parquet('trazo_goias.parquet') t, envpoly
  WHERE ST_Intersects(t.geometry, envpoly.e);
SELECT count(*) AS n_fields_in_envelope FROM fields_env;
"

cd /workspace/data
time duckdb work.db -c "
LOAD spatial;
CREATE TABLE matched_geo AS
  SELECT m.*, ST_Area_Spheroid(f.geom)/10000.0 AS area_ha
  FROM matched m JOIN fields_env f ON f.Id=m.fid;
SELECT '--q11--';
SELECT min(max_single_frac) min_single, avg(max_single_frac) avg_single, avg(union_frac) avg_union FROM matched;
SELECT '--q12 excluded--';
SELECT (SELECT count(*) FROM sfrac) - (SELECT count(*) FROM matched WHERE fid IN (SELECT fid FROM sfrac)) AS n_excluded;
SELECT '--q14 area--';
SELECT sum(area_ha) matched_field_ha FROM matched_geo;
"

cd /workspace/data
duckdb work.db -c "
LOAD spatial;
SET geometry_always_xy = true;
SELECT sum(ST_Area_Spheroid(f.geom)/10000.0) AS ha_xy
FROM matched m JOIN fields_env f ON f.Id=m.fid;
-- also check a single field coordinate to confirm lon/lat
SELECT ST_AsText(ST_Centroid(geom)) FROM fields_env LIMIT 1;
"

cd /workspace/data
duckdb work.db -c "
LOAD spatial; SET geometry_always_xy=true;
SELECT fid, area_ha,
  hansen_loss_area,
  (deforestarea0104+deforestarea0509+deforestarea1014+deforestarea1520+deforestarea2124) AS sum_bands,
  deforestarea2124, mbmode24, mode_year
FROM matched_geo
WHERE hansen_loss_area>0
ORDER BY hansen_loss_area DESC LIMIT 8;
SELECT '--- ranges ---';
SELECT min(deforestarea2124) mn, max(deforestarea2124) mx, avg(area_ha) FROM matched_geo;
"

cd /workspace/data
duckdb work.db -c "
LOAD spatial;
-- membership rows for our municipios
SELECT tier, entity_id, cod_ibge, coop_members, weight, entity_kind, basis
FROM read_parquet('BR_facilities.parquet')
WHERE tier='membership_muni' AND cod_ibge IN ('5212204','5219258');
SELECT '--- geom method/basis for delivery tiers sample ---';
SELECT tier, entity_kind, basis, geom_method, count(*) FROM read_parquet('BR_facilities.parquet')
WHERE tier IN ('intake_point','slaughter_point','mill_point') GROUP BY ALL ORDER BY tier;
"

cd /workspace/data
duckdb work.db -c "
LOAD spatial;
SELECT entity_id, weight, entity_kind, basis FROM read_parquet('BR_facilities.parquet')
WHERE tier='membership_muni' AND entity_id IN ('5212204','5219258');
"
